/* Browser controller: routing, forms, downloads and UI events. */
(async function(){
  'use strict';
  const V=HRViews,{e,button,badge,person,candidate,job}=V;
  const store=await HRRemote.boot(),$=s=>document.querySelector(s);
  const defaults=()=>({page:1,q:'',job:'',stage:'',priority:'',from:'',to:'',full:false,period:'today',resumePage:1,zoom:90,jobStatus:'',interviewStatus:'Scheduled',interviewDate:'',noticeTab:'all'});
  let ui=defaults(),route=['dashboard'],modalTrigger=null,formSnapshot='',busy=false,toastTimer;
  const app=id=>{const a=store.db.applications.find(a=>a.id===id);if(!a)throw Error('Application not found.');return a;};
  function go(path){if(location.hash==='#/'+path){route=path.split('/');render();}else location.hash='/'+path;}
  function notify(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,5500);}
  function render(){
    const db=store.db,page=route[0],active=page==='review'||page==='candidate'?'candidates':page==='success'?'applications':['outbox','templates','mail-log'].includes(page)?'notifications':page;
    const names={dashboard:'Dashboard',applications:'Applications',review:'Resume Review',success:'Status Update',candidates:'Candidates',candidate:'Candidate Profile',jobs:'Job Postings',interviews:'Interviews',reports:'Reports',notifications:'Notification Center',outbox:'Email Outbox',templates:'Email Templates','mail-log':'Notification Log','hr-profile':'My Profile'};
    document.title='JRS | '+(names[page]||'HR Workspace');$('#page-label').textContent=names[page]||'HR Workspace';
    $('#navigation').innerHTML=[['dashboard','home','Dashboard'],['applications','file','Applications'],['candidates','user','Candidates'],['jobs','briefcase','Job Postings'],['interviews','calendar','Interviews'],['reports','chart','Reports'],['notifications','bell','Notifications'],['hr-profile','user','My Profile']].map(([id,ic,title])=>`<a class="nav-item ${active===id?'active':''}" href="#/${id}" ${active===id?'aria-current="page"':''}>${icon(ic)}<span>${title}</span>${id==='applications'?`<span class="nav-count">${db.applications.length}</span>`:id==='notifications'&&db.systemNotifications.some(n=>!n.read)?`<span class="nav-count">${db.systemNotifications.filter(n=>!n.read).length}</span>`:''}</a>`).join('');
    $('#content').innerHTML=V.render(route,db,ui);$('#storage-warning').hidden=!store.error;$('#storage-warning').textContent=store.error;
    $('#user-name').textContent=db.currentUser.name;$('#user-role').textContent=db.currentUser.role==='HR_MANAGER'?'HR Manager':'HR Officer';
    if(page==='applications'||page==='candidates')$('#content .heading-actions')?.insertAdjacentHTML('beforeend',button('application-new',icon('plus')+'Receive Application','','primary'));
    if(page==='candidate'){const c=db.candidates.find(c=>c.id===route[1]);if(c)$('#content .heading-actions')?.insertAdjacentHTML('beforeend',button('candidate-edit','Edit Candidate',c.id)+button('resume-upload','Upload Resume',c.id));if(c){const applications=db.applications.filter(a=>a.candidateId===c.id);if(applications.length>1)$('#content .page-heading')?.insertAdjacentHTML('afterend','<nav class="module-tabs" aria-label="Candidate applications">'+applications.map(a=>V.link('candidate/'+c.id+'/'+a.id,e(job(db,a).title)+' · '+e(a.stage),ui.profileApplicationId===a.id?'active':'')).join('')+'</nav>');}}
    if(page==='review'){const a=db.applications.find(a=>a.id===route[1]);if(!a)return;const c=candidate(db,a);$('#content .heading-actions')?.insertAdjacentHTML('beforeend',button('resume-upload','Upload Resume',c.id));if(c.resume){const canvas=$('.resume-canvas');canvas.innerHTML=`<iframe class="uploaded-resume" src="/api/hr/candidates/${encodeURIComponent(c.id)}/resume" title="${e(c.name)} resume"></iframe>`;$('.resume-toolbar').innerHTML=`<strong>${e(c.resume.filename)}</strong><a class="button secondary compact" target="_blank" rel="noopener" href="/api/hr/candidates/${encodeURIComponent(c.id)}/resume">Open PDF</a>`;const files=document.querySelectorAll('.resume-file p');if(files.length>1)files[1].textContent=c.resume.filename+' · '+(c.resume.size/1024).toFixed(1)+' KB';}else{const sample=/^candidate-\d+$/.test(c.id);if(!sample){$('.resume-canvas').innerHTML=V.empty('No resume uploaded','Upload this candidate’s PDF resume to review it.');$('.resume-toolbar').hidden=true;document.querySelectorAll('[data-action=resume-download],[data-action=resume-print]').forEach(b=>b.disabled=true);}const files=document.querySelectorAll('.resume-file p');if(files.length>1)files[1].textContent=sample?'Sample resume (demonstration data)':'No resume uploaded';}}
  }
  function routeChanged(){ui=defaults();route=(location.hash.replace(/^#\/?/,'')||'dashboard').split('/');ui.profileApplicationId=route[2]||'';render();$('#content').focus({preventScroll:true});window.scrollTo(0,0);}
  function snapshot(){const f=$('#modal form');return f?JSON.stringify([...new FormData(f).entries()]):'';}
  function open(title,subtitle,html,ic='file',tone='blue',wide=false){
    const modal=$('#modal');if(!modal.open)modalTrigger=document.activeElement;
    $('#modal-title').textContent=title;$('#modal-subtitle').textContent=subtitle;$('#modal-icon').innerHTML=`<span class="icon-disc ${tone}">${icon(ic)}</span>`;
    $('#modal-body').innerHTML=html;modal.classList.toggle('wide',wide);if(!modal.open)modal.showModal();formSnapshot=snapshot();
    setTimeout(()=>$('#modal [autofocus]')?.focus(),0);
  }
  function dirty(){return !!formSnapshot&&snapshot()!==formSnapshot;}
  function close(force=false){if(!force&&dirty()&&!confirm('Discard unsaved form changes?'))return;$('#modal').close();formSnapshot='';}
  $('#modal').addEventListener('cancel',ev=>{ev.preventDefault();close();});
  $('#modal').addEventListener('close',()=>{if(modalTrigger?.isConnected)modalTrigger.focus();else $('#content').focus({preventScroll:true});});
  const field=(label,name,value='',type='text',attrs='')=>`<label>${label}<input name="${name}" type="${type}" value="${e(value)}" ${attrs}></label>`;
  const area=(label,name,value='',attrs='')=>`<label>${label}<textarea name="${name}" ${attrs}>${e(value)}</textarea></label>`;
  const choice=(label,name,values,value='')=>`<label>${label}<select name="${name}">${values.map(v=>{const [id,text]=Array.isArray(v)?v:[v,v];return `<option value="${e(id)}" ${id===value?'selected':''}>${e(text)}</option>`;}).join('')}</select></label>`;
  const actions=(submit='Save',danger=false)=>`<footer class="form-footer">${button('close','Cancel','','secondary')}<button type="submit" class="button ${danger?'danger':'primary'}">${icon('arrow')}${submit}</button></footer>`;
  const form=(action,id,fields,submit='Save',danger=false,extra='')=>`<form class="form" data-command="${action}" data-id="${e(id)}" ${extra}><div class="modal-content"><div class="form-error" role="alert" hidden></div>${fields}</div>${actions(submit,danger)}</form>`;
  const candidateCard=a=>{const c=candidate(store.db,a),j=job(store.db,a);return `<span class="field-label">CANDIDATE</span><div class="modal-candidate"><div class="person">${V.avatar(c)}<div><strong>${e(c.name)}</strong><small>${e(j.title)} · ${e(c.email)}</small></div></div><div class="candidate-id"><small>APPLICATION ID</small><strong>${e(a.id)}</strong></div></div>`;};
  const notifySwitch=(title,subtitle,tone='blue',checked=true)=>`<label class="notification-toggle"><span><span class="icon-disc ${tone}">${icon('mail')}</span><span><strong>${title}</strong><small>${subtitle}</small></span></span><input class="switch" type="checkbox" name="notify" ${checked?'checked':''} aria-label="${title}"><small>Notification is saved to the outbox as a draft. Review and send it from Email Outbox.</small></label>`;
  function decision(id,reject=false){const a=app(id),to=reject?'Rejected':'Interview';
    const notesLabel=`<span class="label-row"><span>Internal Notes</span><small>Optional · <span data-note-count>0</span> / 500</small></span>`;
    const fields=candidateCard(a)+`<div><strong>Status Change</strong><p class="form-intro">The application will move to the ${to} category.</p><div class="status-change"><div class="status-box ${V.tone(a.stage)}"><small>CURRENT STATUS</small>${badge(a.stage)}</div>${icon('arrow')}<div class="status-box ${reject?'red':'purple'}"><small>NEW STATUS</small>${badge(to)}</div></div></div>`+(reject?choice('Rejection Reason <span class="required">*</span>','reason',[['','Select a reason'],'Skills do not meet the position requirements','Insufficient relevant experience','Position requirements do not match candidate expectations','Candidate withdrew their application','Position has been filled','Other'])+'<label data-other-reason hidden>Specify reason<input name="reasonDetail" maxlength="300" placeholder="Record the reason"></label>':'')+area(notesLabel,'notes','','maxlength="500" placeholder="Add a private note for the hiring team..."')+notifySwitch(reject?'Prepare rejection notification':'Prepare interview notification',reject?'Prepare an application outcome message for the candidate.':'Prepare a status update and next-step information.',reject?'red':'blue');
    open(reject?'Reject Candidate':'Move Candidate to Interview',reject?'Record a reason before closing this application.':'Confirm the next stage and notification preference.',form(reject?'reject':'move-interview',id,fields,reject?'Reject & Continue':'Confirm & Continue',reject),reject?'x':'calendar',reject?'red':'purple');
  }
  function applicationDetails(id){const a=app(id),c=candidate(store.db,a),j=job(store.db,a);if(a.stage==='Pending Review'){go('review/'+a.id);return;}if(a.stage==='Interview Results'){results(id);return;}if(a.stage==='Offer'){offerDetails(id);return;}if(a.stage==='Rejected'){rejectionDetails(id);return;}
    const meetings=store.db.interviews.filter(i=>i.applicationId===id);
    open('Application details',c.name+' · '+j.title,`<div class="modal-content">${candidateCard(a)}${badge(a.stage)}<dl class="details spaced"><dt>Applied</dt><dd>${V.date(a.appliedDate)}</dd><dt>Position</dt><dd>${e(j.title)}</dd></dl>${meetings.length?'<h4>Interviews</h4>'+meetings.map(i=>`<div class="task-item"><div>${V.date(i.date)} · ${e(i.time)}<small>${e(i.status)}</small></div>${button('interview','Details',i.id,'secondary compact')}</div>`).join(''):''}<div class="modal-actions">${a.stage==='Interview'?button('schedule','Schedule interview',id,'primary')+button('reject','Reject candidate',id,'danger'):''}${V.link('candidate/'+c.id,'View profile','button secondary')}${button('activity','View activity',id,'secondary')}</div></div>`,'file');
  }
  function results(id){const a=app(id),f=a.feedback;open('Interview Results','Review feedback and record the final decision.',`<div class="modal-content">${candidateCard(a)}${f?`<div class="feedback-score">${f.rating}<small> / 5</small></div><p><strong>Recommendation:</strong> ${e(f.recommendation)}</p><div class="note-box spaced">${e(f.notes)}</div><p class="muted spaced">Recorded ${V.datetime(f.recordedAt)}</p>`:V.empty('Feedback not available','Record feedback from the Interviews page.')}<div class="modal-actions">${button('offer-edit','Prepare Offer',id,'primary',!f?'disabled':'')}${button('reject','Reject Candidate',id,'danger')}${V.link('review/'+id,'View Resume','button secondary')}${button('activity','Activity',id,'secondary')}</div></div>`,'results','purple');}
  function rejectionDetails(id){const a=app(id);open('Review Rejection','Confirm the reason and prepare candidate communication.',form('confirm-rejection',id,candidateCard(a)+badge('Rejected')+area('Rejection reason','reason',a.rejectionReason,'required maxlength="500"')+`<p class="form-intro">${a.rejectionConfirmed?'Reason confirmed. Changes will be recorded in the activity history.':'This rejection reason needs confirmation.'}</p><div class="modal-actions">${button('message','Prepare notice',id,'secondary')}${button('activity','View activity',id,'text-button')}</div>`,'Save Reason'), 'x','red');}
  function offerDetails(id){const a=app(id),o=a.offer;if(!o)throw Error('No offer is available.');const expired=o.expiry<HRModel.day();open('Review Offer','Prepare, approve and record candidate responses.',`<div class="modal-content">${candidateCard(a)}<dl class="details"><dt>Monthly salary</dt><dd>SGD ${Number(o.salary).toLocaleString('en-SG')}</dd><dt>Start date</dt><dd>${V.date(o.startDate)}</dd><dt>Expiry</dt><dd class="${expired?'danger-text':''}">${V.date(o.expiry)}${expired?' · Expired':''}</dd><dt>Approval</dt><dd>${e(o.approval)}</dd><dt>Response</dt><dd>${e(o.status)}</dd></dl><div class="note-box spaced">${e(o.terms)}</div><div class="modal-actions">${button('offer-edit','Edit Offer',id,'secondary')}${o.approval!=='Approved'?button('offer-approve','Approve Offer',id,'primary',expired||store.db.currentUser.role!=='HR_MANAGER'?'disabled title="HR Manager approval required"':''):button('offer-message','Prepare Offer Email',id,'primary',expired?'disabled':'')}${button('offer-accept','Record Acceptance',id,'secondary',o.approval!=='Approved'||expired?'disabled':'')}${button('reject','Reject / Close application',id,'text-button')}</div><p class="privacy-note">Approval and acceptance are recorded in the application history. Record acceptance only when the candidate has confirmed.</p></div>`,'offer','green');}
  function offerEdit(id){const a=app(id),o=a.offer||{};open('Prepare Employment Offer','Changes require approval before preparing an offer email.',form('offer',id,candidateCard(a)+field('Monthly salary (SGD)','salary',o.salary||5200,'number','required min="1" max="1000000" step="0.01"')+`<div class="form-grid">${field('Start date','startDate',o.startDate||HRModel.day(30),'date','required')}${field('Respond by','expiry',o.expiry||HRModel.day(7),'date',`required min="${HRModel.day()}"`)}</div>`+area('Offer terms','terms',o.terms||'Full-time position. Standard company benefits.','required maxlength="3000"'),'Save Offer'),'offer','green');}
  function schedule(id,interviewId){const a=app(id),i=interviewId?store.db.interviews.find(i=>i.id===interviewId):store.db.interviews.find(i=>i.applicationId===id&&i.status==='Scheduled');if(i&&i.status!=='Scheduled')throw Error('This interview cannot be edited.');
    open(i?'Reschedule Interview':'Schedule Interview','All times are Singapore time (UTC+08:00). Overlapping bookings are blocked.',form('schedule',id,candidateCard(a)+`<div class="form-grid">${field('Date','date',i?.date||HRModel.day(1),'date',`required min="${HRModel.day()}"`)}${field('Time','time',i?.time||'10:00','time','required')}</div><div class="form-grid">${choice('Duration','duration',[['15','15 minutes'],['30','30 minutes'],['45','45 minutes'],['60','60 minutes'],['90','90 minutes'],['120','120 minutes']],String(i?.duration||60))}${choice('Meeting format','format',['Video','On-site','Phone'],i?.format||'Video')}</div>`+field('Interviewer','interviewer',i?.interviewer||store.db.currentUser.name,'text','required maxlength="100"')+field('Meeting link, room or phone details','location',i?.location||'','text','required maxlength="300" placeholder="e.g. Meeting Room A or video meeting link"')+area('Internal notes','notes',i?.notes||'','maxlength="500"')+notifySwitch('Prepare schedule notification','Include the date, time and meeting details.'),i?'Save New Schedule':'Schedule Interview',false,`data-interview-id="${e(i?.id||'')}"`),'calendar','purple');
  }
  function interviewDetails(id){const i=store.db.interviews.find(i=>i.id===id);if(!i)throw Error('Interview not found.');const a=app(i.applicationId),started=new Date(i.date+'T'+i.time+':00+08:00').getTime()+i.duration*60000<=Date.now();open('Interview details','Meeting information and feedback.',`<div class="modal-content">${candidateCard(a)}<dl class="details"><dt>Date</dt><dd>${V.date(i.date)}</dd><dt>Time</dt><dd>${e(i.time)} · ${i.duration} minutes</dd><dt>Interviewer</dt><dd>${e(i.interviewer)}</dd><dt>Format</dt><dd>${e(i.format)}</dd><dt>Details</dt><dd>${e(i.location)}</dd><dt>Status</dt><dd>${badge(i.status)}</dd></dl>${i.notes?'<div class="note-box spaced">'+e(i.notes)+'</div>':''}${i.feedback?`<h4>Feedback · ${i.feedback.rating}/5</h4><div class="note-box">${e(i.feedback.notes)}</div>`:''}<div class="modal-actions">${button('calendar-download','Download calendar event',id,'secondary')}${i.status==='Scheduled'?button('interview-reschedule','Reschedule',id,'secondary')+button('interview-feedback','Record Feedback',id,'primary',!started?'disabled title="Feedback becomes available after the interview ends"':'')+button('interview-cancel','Cancel interview',id,'text-button'):''}</div>${i.status==='Scheduled'&&!started?'<p class="privacy-note">Feedback can be recorded once the interview has ended.</p>':''}</div>`,'calendar','purple');}
  function messageForm(id,notificationId){const a=app(id),c=candidate(store.db,a),j=job(store.db,a),n=notificationId?store.db.notifications.find(n=>n.id===notificationId):null;const rejected=a.stage==='Rejected';open('Candidate Message','Prepare and review a draft. Send the saved message from Email Outbox.',form('message',id,candidateCard(a)+choice('Email template','templateId',[['','Custom message'],...store.db.templates.filter(t=>t.active).map(t=>[t.id,t.name])],n?.templateId||'')+field('To','to',c.email,'email','readonly')+field('Subject','subject',n?.subject||(rejected?'Application update — ':'Next steps — ')+j.title,'text','required maxlength="200"')+area('Message','body',n?.body||('Hello '+c.name+',\n\n'+(rejected?'Thank you for your interest in '+j.title+'. After careful consideration, we will not be progressing your application for this position. We wish you the best in your job search.':'Thank you for your application for '+j.title+'. We will follow up with the next steps shortly.')+'\n\nBest regards,\n'+store.db.currentUser.name),'required maxlength="6000" rows="9"')+(n?button('email-download',icon('download')+'Download saved draft (.eml)',n.id,'secondary'):'')+'<p class="privacy-note">Private rejection reasons and internal notes are not added to the candidate email.</p>','Save Email Draft',false,`data-notification-id="${e(n?.id||'')}"`),'mail','blue');}
  function taskForm(id){open('Create Follow-up Task','Record preparation work for the hiring team.',form('task',id,candidateCard(app(id))+field('Task title','title','','text','required maxlength="150" placeholder="e.g. Prepare technical interview questions"')+`<div class="form-grid">${field('Assigned to','assignee',store.db.currentUser.name,'text','required maxlength="100"')}${field('Due date','due',HRModel.day(1),'date',`required min="${HRModel.day()}"`)}</div>`+area('Task notes','notes','','maxlength="1000"'),'Create Task'),'briefcase','green');}
  function jobForm(id){const j=id?store.db.jobs.find(j=>j.id===id):null;open(j?'Edit Job Posting':'Create Job Posting','Set the role requirements and posting status.',form('job-save',id||'',field('Job title','title',j?.title||'','text','required maxlength="100"')+`<div class="form-grid">${field('Department','department',j?.department||'Engineering','text','required maxlength="100"')}${choice('Employment type','type',['Full-time','Part-time','Contract','Internship'],j?.type||'Full-time')}</div><div class="form-grid">${field('Location','location',j?.location||'Singapore','text','required maxlength="100"')}${choice('Work mode','mode',['On-site','Hybrid','Remote'],j?.mode||'On-site')}</div><div class="form-grid">${field('Experience','experience',j?.experience||'2+ years','text','required maxlength="100"')}${field('Education','education',j?.education||'Diploma or Degree','text','required maxlength="150"')}</div>`+field('Required skills (comma separated)','skills',j?.skills.join(', ')||'','text','required maxlength="500"')+area('Minimum requirements (one per line)','requirements',j?.requirements.join('\n')||'','required maxlength="3000"')+area('Key responsibilities','description',j?.description||'','required maxlength="3000"')+choice('Posting status','status',['Active','Draft','Closed'],j?.status||'Active'),'Save Job Posting'),'briefcase','blue',true);}
  function download(blob,filename){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
  function csv(headers,rows,name){const cell=x=>'"'+String(x??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';download(new Blob(['\ufeff'+[headers,...rows].map(row=>row.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),name);}
  function exportApplications(){const items=V.filtered(store.db,ui);csv(['Application ID','Candidate','Email','Position','Stage','Priority','Applied Date'],items.map(a=>[a.id,candidate(store.db,a).name,candidate(store.db,a).email,job(store.db,a).title,a.stage,a.priority,a.appliedDate]),'JRS-Applications.csv');notify('Exported '+items.length+' matching applications.');}
  function dataSettings(){open('Workspace Data','Recruitment records are stored in MySQL.',`<div class="modal-content"><p>${store.db.applications.length} applications · ${store.db.jobs.length} jobs</p><p class="muted spaced">Use database backup tools to include uploaded resumes and account settings.</p><div class="modal-actions spaced">${button('backup','Export HR records (JSON)')}${button('workspace-refresh','Refresh Workspace')}</div></div>`,'file');}
  function commit(command,p){return store.commit(command,p);}
  const extra=HRExtra.attach({store,open,form,field,area,choice,render,go,notify,close});
  function formError(form,error){const target=form.querySelector('.form-error');target.hidden=false;target.textContent=error.message;target.scrollIntoView({block:'nearest'});}

  document.addEventListener('submit',async ev=>{
    const f=ev.target;if(!f.matches('#modal form'))return;ev.preventDefault();if(busy)return;
    if(!f.reportValidity())return;busy=true;const submits=[...f.querySelectorAll('[type=submit]')];submits.forEach(b=>b.disabled=true);
    try{
      const data=Object.fromEntries(new FormData(f)),cmd=f.dataset.command,id=f.dataset.id;
      if(await extra.submit(cmd,id,data,f))return;
      if(f.elements.notify)data.notify=!!f.elements.notify.checked;
      if(cmd==='filters'){if(data.from&&data.to&&data.from>data.to)throw Error('Start date must be before end date.');Object.assign(ui,data,{full:true,page:1});close(true);render();return;}
      const p={...data,applicationId:id};
      if(cmd==='reject'&&p.reason==='Other'){if(!String(data.reasonDetail||'').trim())throw Error('Specify the rejection reason.');p.reason='Other: '+String(data.reasonDetail).trim();}
      if(cmd==='schedule')p.interviewId=f.dataset.interviewId||undefined;
      if(cmd==='feedback'||cmd==='cancel-interview')p.interviewId=f.dataset.interviewId;
      if(cmd==='message')p.notificationId=f.dataset.notificationId||undefined;
      if(cmd==='job-save'){p.id=id||undefined;delete p.applicationId;}
      if(['candidate-save','template-save'].includes(cmd)){p.id=id||undefined;delete p.applicationId;}
      if(cmd==='application-create'){delete p.applicationId;p.candidate={name:data.name,email:data.email,phone:data.phone,location:data.location,experience:data.experience,education:data.education,skills:data.skills};if(p.candidateId)delete p.candidate;}
      const r=await commit(cmd,p);close(true);render();
      if(['move-interview','reject','feedback','offer','accept-offer'].includes(cmd)&&r.activity){go('success/'+r.activity.id);return;}
      if(cmd==='schedule'){go('interviews');notify('Interview saved'+(p.notify?'; notification draft added to outbox.':'.'));}
      else if(cmd==='message'){go('outbox');notify('Email draft saved. No email has been sent.');}
      else if(cmd==='application-create'){go('review/'+r.application.id);notify('Application received.');}
      else if(cmd==='job-save'){go('jobs');notify('Job posting saved.');}
      else notify('Changes saved.');
    }catch(error){formError(f,error);}finally{busy=false;submits.forEach(b=>b.disabled=false);}
  });

  document.addEventListener('click',async ev=>{
    const b=ev.target.closest('[data-action]');if(!b||b.disabled)return;
    // Buttons inside forms must never trigger the browser's implicit submit.
    if(b.closest('form')&&b.type==='submit')ev.preventDefault();
    const id=b.dataset.id,action=b.dataset.action;
    if(busy)return;busy=true;b.disabled=true;
    try{
      if(await extra.action(action,id))return;
      switch(action){
        case 'close':close();break;
        case 'queue':ui.stage=id;ui.full=true;ui.page=1;render();break;
        case 'full-queue':ui.full=true;ui.page=1;render();break;
        case 'clear-filters':ui=defaults();ui.interviewStatus='';render();break;
        case 'page':ui.page=Math.max(1,Number(id));render();break;
        case 'period':ui.period=id;render();break;
        case 'export':exportApplications();break;
        case 'filters':open('Filter Applications','Apply filters to the work queue.',form('filters','',V.select?choice('Position','job',[['','All positions'],...store.db.jobs.map(j=>[j.id,j.title])],ui.job)+choice('Stage','stage',[['','All stages'],...HRModel.STAGES],ui.stage)+choice('Priority','priority',[['','All priorities'],'High','Normal'],ui.priority)+`<div class="form-grid">${field('Applied from','from',ui.from,'date')}${field('Applied to','to',ui.to,'date')}</div>`:'','Apply Filters'),'filter');break;
        case 'application':applicationDetails(id);break;
        case 'move-interview':decision(id,false);break;
        case 'reject':decision(id,true);break;
        case 'review-prev':case 'review-next':{const list=store.db.applications.filter(a=>a.stage==='Pending Review'||a.id===id),i=list.findIndex(a=>a.id===id),n=list[i+(action==='review-next'?1:-1)];if(n)go('review/'+n.id);break;}
        case 'resume-page':ui.resumePage=Number(id);render();break;
        case 'zoom':ui.zoom=Math.max(60,Math.min(150,ui.zoom+Number(id)));render();break;
        case 'fullscreen':if(document.fullscreenElement)document.exitFullscreen().catch(()=>notify('Fullscreen is unavailable.'));else $('#resume-viewer').requestFullscreen?.().catch(()=>notify('Fullscreen is unavailable.'));break;
        case 'resume-download':{const a=app(id),c=candidate(store.db,a);if(c.resume){const link=document.createElement('a');link.href='/api/hr/candidates/'+encodeURIComponent(c.id)+'/resume?download=1';link.click();break;}if(!/^candidate-\d+$/.test(c.id))throw Error('No resume has been uploaded.');download(HRResume.pdf(c,job(store.db,a)),c.name.replaceAll(' ','_')+'_Resume.pdf');break;}
        case 'resume-print':{const a=app(id),c=candidate(store.db,a),j=job(store.db,a),w=window.open('','_blank');if(!w)throw Error('Allow pop-ups to print the resume.');w.document.write('<!doctype html><html><head><title>'+e(c.name)+' Resume</title><link rel="stylesheet" href="'+new URL('styles.css',location.href).href+'"><style>body{background:white}.resume-paper{width:190mm;min-height:270mm;margin:0 auto;break-after:page}.resume-paper:last-child{break-after:auto}@page{size:A4;margin:10mm}</style></head><body>'+HRResume.html(c,j,1)+HRResume.html(c,j,2)+'</body></html>');w.document.close();w.addEventListener('load',()=>{w.focus();w.print();},{once:true});break;}
        case 'activity':{const a=app(id);open('Application Activity',candidate(store.db,a).name+' · '+id,`<div class="modal-content">${V.timeline(store.db,id)}</div>`,'clock');break;}
        case 'schedule':schedule(id);break;
        case 'schedule-select':{const eligible=store.db.applications.filter(a=>a.stage==='Interview');open('Choose Candidate','Only candidates in the Interview stage can be scheduled.',`<div class="modal-content">${eligible.length?eligible.map(a=>`<div class="task-item">${person(store.db,a)}${button('schedule','Schedule',a.id,'secondary compact')}</div>`).join(''):V.empty('No eligible candidates','Review a resume and move the candidate to Interview first.')}</div>`,'calendar','purple');break;}
        case 'interview':interviewDetails(id);break;
        case 'interview-reschedule':{const i=store.db.interviews.find(i=>i.id===id);schedule(i.applicationId,id);break;}
        case 'interview-cancel':{const i=store.db.interviews.find(i=>i.id===id);open('Cancel Interview','The candidate remains in Interview and can be rescheduled.',form('cancel-interview',i.applicationId,candidateCard(app(i.applicationId))+area('Cancellation reason','reason','','required maxlength="500"'),'Cancel Interview',true,`data-interview-id="${id}"`),'x','red');break;}
        case 'interview-feedback':{const i=store.db.interviews.find(i=>i.id===id);open('Record Interview Feedback','Completing feedback moves the application to Interview Results.',form('feedback',i.applicationId,candidateCard(app(i.applicationId))+choice('Rating','rating',[['1','1 — Poor'],['2','2 — Below expectations'],['3','3 — Meets expectations'],['4','4 — Strong'],['5','5 — Excellent']],'4')+choice('Recommendation','recommendation',['Proceed','Hold','Reject'],'Proceed')+area('Interview feedback','notes','','required maxlength="3000"'),'Complete Interview',false,`data-interview-id="${id}"`),'results','purple');break;}
        case 'calendar-download':{const i=store.db.interviews.find(i=>i.id===id),a=app(i.applicationId),d=new Date(i.date+'T'+i.time+':00+08:00'),end=new Date(d.getTime()+i.duration*60000),fmt=x=>x.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const clean=x=>String(x).replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const content=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//JRS//HR Workspace//EN','BEGIN:VEVENT','UID:'+id+'@jrs.local','DTSTAMP:'+fmt(new Date()),'DTSTART:'+fmt(d),'DTEND:'+fmt(end),'SUMMARY:'+clean('Interview: '+candidate(store.db,a).name+' — '+job(store.db,a).title),'LOCATION:'+clean(i.location),'DESCRIPTION:'+clean('Interviewer: '+i.interviewer+'\n'+i.notes),'STATUS:'+(i.status==='Cancelled'?'CANCELLED':'CONFIRMED'),'END:VEVENT','END:VCALENDAR'].join('\r\n');download(new Blob([content],{type:'text/calendar;charset=utf-8'}),'JRS-Interview.ics');break;}
        case 'offer-edit':offerEdit(id);break;
        case 'offer-approve':if(confirm('Approve these offer terms?')){await commit('approve-offer',{applicationId:id});render();offerDetails(id);}break;
        case 'offer-message':await commit('offer-message',{applicationId:id});close(true);go('outbox');notify('Offer email draft prepared.');break;
        case 'offer-accept':open('Record Offer Acceptance','Use this after the candidate has confirmed acceptance.',form('accept-offer',id,candidateCard(app(id))+area('Acceptance record','notes','','required maxlength="1000" placeholder="Record when and how the candidate accepted."'),'Confirm Acceptance'),'check','green');break;
        case 'message':messageForm(id);break;
        case 'message-edit':{const n=store.db.notifications.find(n=>n.id===id);if(n.status!=='Draft'){open(n.status+' Message',n.status==='Sent'?'This message was accepted by the email server.':'This message is read-only.',`<div class="modal-content"><h3>${e(n.subject)}</h3><p class="muted">${e(n.to)}</p><div class="note-box spaced">${e(n.body)}</div></div>`,'mail','gray');}else messageForm(n.applicationId,id);break;}
        case 'email-download':{const n=store.db.notifications.find(n=>n.id===id);if(n.status!=='Draft')throw Error('This draft is no longer current.');const subject=n.subject.replace(/[\r\n]/g,' '),to=n.to.replace(/[\r\n]/g,'');const data='To: '+to+'\r\nSubject: '+subject+'\r\nMIME-Version: 1.0\r\nContent-Type: text/plain; charset=UTF-8\r\nX-Unsent: 1\r\n\r\n'+n.body.replace(/\r?\n/g,'\r\n');download(new Blob([data],{type:'message/rfc822'}),'JRS-Email-Draft.eml');break;}
        case 'notice-read':await commit('read-notification',{id});render();break;
        case 'read-all':await commit('read-all',{});render();notify('All notifications marked as read.');break;
        case 'task':taskForm(id);break;
        case 'task-complete':await commit('complete-task',{id});render();notify('Task completed.');break;
        case 'candidate-notes':{const a=app(id);open('Private Candidate Note','Visible only inside the HR workspace.',form('candidate-notes',id,area('Note','notes',candidate(store.db,a).notes,'required maxlength="3000"'),'Save Note'),'edit');break;}
        case 'job-new':jobForm();break;
        case 'job-edit':jobForm(id);break;
        case 'job-close':case 'job-open':if(confirm(action==='job-close'?'Close this job posting? Existing applications remain available, but advancement and new scheduling will be blocked.':'Reopen this job posting?')){await commit('job-status',{id,status:action==='job-close'?'Closed':'Active'});render();notify('Job status updated.');}break;
        case 'job-applications':go('applications');setTimeout(()=>{ui.job=id;ui.full=true;render();},0);break;
        case 'export-report':csv(['Position','Total applications','Pending Review','Interview','Interview Results','Offer','Rejected','Hired'],store.db.jobs.map(j=>[j.title,store.db.applications.filter(a=>a.jobId===j.id).length,...HRModel.STAGES.map(s=>store.db.applications.filter(a=>a.jobId===j.id&&a.stage===s).length)]),'JRS-Recruitment-Report.csv');break;
        case 'data-settings':dataSettings();break;
        case 'backup':download(new Blob([store.error&&store.raw?store.raw:JSON.stringify(store.db,null,2)],{type:'application/json'}),'JRS-Workspace-Backup.json');break;
      }
    }catch(error){notify(error.message);}finally{busy=false;if(b.isConnected)b.disabled=false;}
  });
  // Close a detail dialog when a route link inside it is followed.
  document.addEventListener('click',ev=>{const a=ev.target.closest('a[href^="#/"]');if(a&&$('#modal').open){if(dirty()&&!confirm('Discard unsaved form changes?')){ev.preventDefault();return;}close(true);}});
  document.addEventListener('input',ev=>{
    if(ev.target.matches('[data-search]')){const input=ev.target,position=input.selectionStart;ui.q=input.value;ui.page=1;render();const next=$('[data-search]');next?.focus();next?.setSelectionRange(position,position);}
    if(ev.target.name==='notes'&&$('#modal [data-note-count]'))$('#modal [data-note-count]').textContent=ev.target.value.length;
  });
  document.addEventListener('change',async ev=>{
    const target=ev.target;
    if(target.name==='templateId'&&target.value){try{const f=target.closest('form'),r=await store.request('hr/templates/'+encodeURIComponent(target.value)+'/preview',{method:'POST',body:{applicationId:f.dataset.id}});f.elements.subject.value=r.subject;f.elements.body.value=r.body;}catch(error){target.value='';notify(error.message);}}
    if(target.name==='candidateId'&&$('[data-new-candidate]')){const fields=$('[data-new-candidate]');fields.hidden=!!target.value;fields.querySelectorAll('input').forEach(input=>input.disabled=!!target.value);}
    if(target.dataset.filter){ui[target.dataset.filter]=target.value;ui.page=1;render();}
    if(target.name==='reason'&&$('[data-other-reason]')){const other=$('[data-other-reason]');other.hidden=target.value!=='Other';other.querySelector('input').required=!other.hidden;}
  });
  window.addEventListener('hashchange',routeChanged);
  document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
  routeChanged();
})().catch(error=>{const host=document.querySelector('#login-screen');host.hidden=false;host.innerHTML='<div class="login-card"><h1>Unable to open HR workspace</h1><p id="boot-error"></p><a class="button primary" href="/">Try again</a></div>';document.querySelector('#boot-error').textContent=error.message;});
